// Input: HTML content from previous node 'Switch1'
const htmlContent = $input.first().json.textAsHtml || $input.first().json.text || "";

// Function to extract all http/https URLs
function extractUrlsFromHtml(html) {
    const urls = [];
    const regex = /https?:\/\/[^\s"'<>]+/g; // Matches http or https URLs
    let match;
    while ((match = regex.exec(html)) !== null) {
        urls.push(match[0]);
    }
    // Remove duplicates
    return [...new Set(urls)];
}

// Extract all URLs
const extractedUrls = extractUrlsFromHtml(htmlContent);

// Filter URLs that start with specific domains
const filteredUrls = extractedUrls.filter(url =>
    url.startsWith("https://www.fda.gov/") ||
url.startsWith("https://www.fsis.usda.gov/recalls-alerts/") ||    url.startsWith("https://www.cpsc.gov/") || url.startsWith("https://www.accessdata.fda.gov/")|| url.startsWith("https://ld.scoutyourcase.com/")
);

// Map each filtered URL to an object
const urlsArray = filteredUrls.map(u => ({ url: u }));

// Always return data, even if no matches found
return [{ json: { output: { urls: urlsArray } } }];

// n8n Code Node
// Extract content between "FSIS Announcement" and "Last Updated: <date>" from HTML input

const htmlContent = $input.first().json.data;

function extractFsisAnnouncement(html) {
  if (!html) return { sliceText: "", lastUpdated: null };

  // Regex pattern for Last Updated date (Month DD, YYYY)
  const lastUpdatedRegex = /Last\s*Updated:\s*([A-Za-z]{3,9}\.?[\s\-]?\d{1,2},?\s*\d{4})/i;

  // Normalize the HTML for easier searching
  const normalized = html
    .replace(/\s+/g, " ")
    .replace(/<br\s*\/?>/gi, "\n")
    .replace(/<\/p>/gi, "\n")
    .replace(/<\/?[^>]+>/g, ""); // strip tags

  // Find FSIS Announcement start
  const startIdx = normalized.toLowerCase().indexOf("fsis announcement");
  if (startIdx === -1) {
    return { sliceText: "", lastUpdated: null };
  }

  // Find "Last Updated: <date>" after that
  const match = lastUpdatedRegex.exec(normalized.slice(startIdx));
  if (!match) {
    return { sliceText: "", lastUpdated: null };
  }

  const endIdx = startIdx + match.index; // where "Last Updated" starts
  const betweenText = normalized
    .slice(startIdx + "fsis announcement".length, endIdx)
    .replace(/\n{2,}/g, "\n")
    .trim();

  const lastUpdated = match[1]?.trim() || null;

  return { sliceText: betweenText, lastUpdated };
}

// Run extraction
const { sliceText, lastUpdated } = extractFsisAnnouncement(htmlContent);

// Combine sliceText and lastUpdated into a single string
const data = `${sliceText} Last Updated: ${lastUpdated}`;

// Return result
return [
  {
    json: {
      data, // combined content of the extracted text and the lastUpdated
    },
  },
];

// n8n Function Node
// Groups recall rows by recalling firm
// Stores products, quantities, recall numbers, and event URLs

const items = $input.all();
const grouped = {};

// Helper: safely convert quantity to number
function parseQuantity(qty) {
  if (!qty) return 0;
  const num = String(qty).replace(/,/g, "").match(/\d+/);
  return num ? Number(num[0]) : 0;
}

// 1️⃣ Group rows by recalling firm
for (const item of items) {
  const row = item.json;
  const firm = row["Recalling Firm"] || row["recallingFirm"];
  if (!firm) continue;

  if (!grouped[firm]) {
    grouped[firm] = {
      recallingFirm: firm,

      header: {
        category: row["Category"],
        ProductType:row["Product Type"],
        city: row["City"],
        state: row["State"],
        country: row["Country"],
        recallClass: row["Classification"],
        recallReason: row["Reason for Recall"],
        initiationDate: row["Recall Initiation Date"],
        reportDate: row["Report Date"]
      },

      products: [],          // product descriptions
      quantity: [],          // raw quantities
      totalQuantity: 0,      // ✅ NEW: summed quantity
      recallNumbers: [],     // ✅ NEW: recall number list
      eventIds: []           // ✅ NEW: event ID URLs
    };
  }

  // Product description
  grouped[firm].products.push(
    row["Product Description"] || "N/A"
  );

  // Quantity (store raw + add to total)
  const qty = row["Product Quantity"] || "0";
  grouped[firm].quantity.push(qty);
  grouped[firm].totalQuantity += parseQuantity(qty);

  // Recall Number
  if (row["Recall Number"]) {
    grouped[firm].recallNumbers.push(row["Recall Number"]);
  }

  // Event ID → URL transform
  if (row["Event ID"]) {
    grouped[firm].eventIds.push(
      `https://www.accessdata.fda.gov/scripts/ires/?Event=${row["Event ID"]}`
    );
  }
}

// 2️⃣ Convert grouped object to n8n output format
const output = [];

for (const firm in grouped) {
  output.push({
    json: grouped[firm]
  });
}

return output;

// ------------------------------
// Read snapshot data (EXACT STRUCTURE)
// ------------------------------
const first = $input.first()?.json || {};
const snapshots = Array.isArray(first.data) ? first.data : [];

// ------------------------------
// Helper: safe clean text
// ------------------------------
function clean(t) {
  if (t === null || t === undefined) return "N/A";
  const s = String(t).trim();
  if (/{{\s*[\w.]+\s*}}/i.test(s)) return "N/A";
  if (/{%\s*[\w.]+\s*%}/i.test(s)) return "N/A";
  if (!/[a-zA-Z0-9]/.test(s)) return "N/A";
  return s;
}

// ------------------------------
// Build Recall Snapshot HTML
// ------------------------------
let html = "";

snapshots.forEach(snapshot => {
  const brand = clean(snapshot.recallingFirm);
  const h = snapshot.header || {};

  const descriptions = Array.isArray(snapshot.products) ? snapshot.products : [];
  const quantities = Array.isArray(snapshot.quantity) ? snapshot.quantity : [];
  const eventLinks = Array.isArray(snapshot.eventIds) ? snapshot.eventIds : [];
  const recallNumbers = Array.isArray(snapshot.recallNumbers) ? snapshot.recallNumbers : [];
  const totalQty = snapshot.totalQuantity ?? "N/A";

  html += `
<div style="margin-bottom:36px; font-family:Arial, sans-serif; line-height:1.6;">

      <h3 style="margin:0 0 10px 0; font-size:18px; color:#111;">
        🔔 Recall Leads Snapshot – ${brand}
</h3>

      <p><strong>Brand Name:</strong> ${brand}</p>
<p><strong>Product Type:</strong> ${clean(h.ProductType)}</p>
<p><strong>Classification:</strong> ${clean(h.recallClass)}</p>
<p><strong>Number of Units Sold:</strong> Multiple (see table below)</p>
<p><strong>Total Quantity Recalled:</strong> ${clean(totalQty)}</p>
<p><strong>City:</strong> ${clean(h.city)}</p>
<p><strong>Country:</strong> ${clean(h.country)}</p>
<p><strong>Recall Reason:</strong> ${clean(h.recallReason)}</p>
<p><strong>Recall Initiation Date:</strong> ${clean(h.initiationDate)}</p>
<p><strong>Report Date:</strong> ${clean(h.reportDate)}</p>

      <table style="width:100%; border-collapse:collapse; margin-top:14px;">
<thead>
<tr>
<th style="border:1px solid #ddd; padding:8px; text-align:left;">
              Brand Name
</th>
<th style="border:1px solid #ddd; padding:8px; text-align:left;">
              Product Description
</th>
<th style="border:1px solid #ddd; padding:8px; text-align:left;">
              Quantity
</th>
<th style="border:1px solid #ddd; padding:8px; text-align:left;">
              Recall Number
</th>
<th style="border:1px solid #ddd; padding:8px; text-align:left;">
              FDA Event Link
</th>
</tr>
</thead>
<tbody>
          ${
            descriptions.map((desc, idx) => `
<tr>
<td style="border:1px solid #ddd; padding:8px; vertical-align:top;">
                  ${brand}
</td>
<td style="border:1px solid #ddd; padding:8px; vertical-align:top;">
                  ${clean(desc)}
</td>
<td style="border:1px solid #ddd; padding:8px; white-space:nowrap;">
                  ${clean(quantities[idx] ?? "N/A")}
</td>
<td style="border:1px solid #ddd; padding:8px;">
                  ${clean(recallNumbers[idx] ?? "N/A")}
</td>
<td style="border:1px solid #ddd; padding:8px;">
                  ${
                    eventLinks[idx]
                      ? `<a href="${eventLinks[idx]}" target="_blank">View Event</a>`
                      : "N/A"
                  }
</td>
</tr>
            `).join("")
          }
</tbody>
</table>

      <hr style="border:none; border-top:1px solid #ddd; margin-top:18px;">
</div>
  `;
});

// ------------------------------
// Final HTML wrapper
// ------------------------------
const finalHtml = `
<!DOCTYPE html>
<html>
<body style="padding:16px; background:#ffffff;">
    ${html || "<p>No recall snapshot data found.</p>"}
</body>
</html>
`;

return [{ json: { html: finalHtml } }];

/**
 * n8n Function Node
 * Purpose: Extract structured rows from HTML TABLE email content
 * Output: ONE item with parent metadata + rows array
 */

// 1️⃣ Get HTML safely from common email nodes
const html =
  items[0].json.html ||
  items[0].json.body ||
  items[0].json.textHtml ||
  items[0].json.messageHtml ||
  "";

if (!html) {
  return [{
    json: {
      error: "No HTML found in email payload",
      rows: []
    }
  }];
}

// 2️⃣ Extract first table
const tableMatch = html.match(/<table[\s\S]*?<\/table>/i);
if (!tableMatch) {
  return [{
    json: {
      error: "No <table> found in email HTML",
      rows: []
    }
  }];
}

const tableHtml = tableMatch[0];

// 3️⃣ Extract rows
const rowRegex = /<tr[\s\S]*?<\/tr>/gi;
const rows = tableHtml.match(rowRegex) || [];

// 4️⃣ Extract cell values
function extractCells(rowHtml) {
  const cellRegex = /<(td|th)[^>]*>([\s\S]*?)<\/\1>/gi;
  const cells = [];
  let match;

  while ((match = cellRegex.exec(rowHtml)) !== null) {
    cells.push(
      match[2]
        .replace(/<br\s*\/?>/gi, " ")
        .replace(/<[^>]+>/g, "")
        .replace(/&nbsp;/g, " ")
        .replace(/&amp;/g, "&")
        .replace(/\s+/g, " ")
        .trim()
    );
  }
  return cells;
}

// 5️⃣ Header row
const headerCells = extractCells(rows[0] || []);
const headers = headerCells.map(h => h.trim());

// 6️⃣ Build row objects
const dataRows = [];

for (let i = 1; i < rows.length; i++) {
  const values = extractCells(rows[i]);
  if (!values.length) continue;

  const rowObj = {};
  headers.forEach((header, idx) => {
    rowObj[header] = values[idx] || "";
  });

  dataRows.push(rowObj);
}

// 7️⃣ Parent wrapper
const parentPayload = {
  source: "email_table",
  extracted_at: new Date().toISOString(),
  row_count: dataRows.length,
  rows: dataRows
};

// 8️⃣ Return SINGLE item
return [
  {
    json: parentPayload
  }
];

/**
 * Deduplicate incoming rows using:
 * Product Description AND Recalling Firm
 * Return FULL rows with all parameters
 */

const incoming = $('Code in JavaScript3').first().json.rows || [];
const existing = $input.first().json.data2 || [];

function normalize(val) {
  return (val || "")
    .toLowerCase()
    .replace(/\s+/g, " ")
    .trim();
}

// Build existing uniqueness set (AND condition)
const existingKeySet = new Set();

for (const row of existing) {
  const desc = normalize(row["Product Description"]);
  const firm = normalize(row["Recalling Firm"]);

  if (desc && firm) {
    existingKeySet.add(`${desc}||${firm}`);
  }
}

const seenKeys = new Set();
const uniqueNewRows = [];

for (const row of incoming) {
  const desc = normalize(row["Product Description"]);
  const firm = normalize(row["Recalling Firm"]);

  if (!desc || !firm) continue;

  const key = `${desc}||${firm}`;

  // ✅ AND condition enforced here
  if (existingKeySet.has(key)) continue;
  if (seenKeys.has(key)) continue;

  seenKeys.add(key);
  uniqueNewRows.push(row); // full row preserved
}

return uniqueNewRows;
